#!/bin/bash -p
#SBATCH -A mt01 -p advanced -N1 --ntasks=1 -c 48 --mem=800G -t 04:00:00
#SBATCH --no-requeue
set -euo pipefail
umask 077
export PATH=/usr/local/bin:/usr/bin:/bin CUDA_VISIBLE_DEVICES='' PYTHONDONTWRITEBYTECODE=1
PY=$(command -v python3)
exec "$PY" -I -B - "$1" <<'P'
import base64,hashlib,json,sys,zlib
raw=zlib.decompress(base64.b64decode(''))
if hashlib.sha256(raw).hexdigest()!='70a5b78d3acac62acdd508b4f8f8095a10bd9dbc2daef1dd45cc6cae63b72647':raise ValueError('Embedded source differs')
authority=json.load(open(sys.argv[1]))
if authority['identity']!='7fdc0ac4fb833b327fe90de119fa2bc70415f825736f341124d00962a9ec1ad2':raise ValueError('Configuration differs')
namespace={};exec(compile(raw,'p.py','exec'),namespace)
raise SystemExit(namespace['main'](authority))
P
